namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public List<int> Ratings { get; set; } = [];

    public double AverageRating => Ratings.Count > 0 ? Ratings.Average() : 0;
}

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes =
        [
            new Recipe
            {
                Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Ingredients = "Pizza dough\nSan Marzano tomatoes\nFresh mozzarella\nFresh basil\nOlive oil\nSalt",
                Steps = "1. Preheat oven to 475°F (245°C).\n2. Roll out dough on a floured surface.\n3. Spread crushed tomatoes evenly.\n4. Tear mozzarella and distribute over sauce.\n5. Bake for 10-12 minutes until crust is golden.\n6. Top with fresh basil and a drizzle of olive oil.",
                Ratings = [5, 4, 5, 4]
            },
            new Recipe
            {
                Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
                Ingredients = "Spaghetti\nGuanciale or pancetta\nEggs\nPecorino Romano\nBlack pepper",
                Steps = "1. Cook spaghetti in salted water until al dente.\n2. Crisp guanciale in a skillet.\n3. Whisk eggs with grated pecorino and pepper.\n4. Toss hot pasta with guanciale.\n5. Remove from heat and stir in egg mixture quickly.\n6. Serve immediately with extra pecorino.",
                Ratings = [5, 5, 4]
            },
            new Recipe
            {
                Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
                Ingredients = "Chicken breast\nYogurt\nGaram masala\nTurmeric\nCumin\nTomato sauce\nHeavy cream\nGarlic\nGinger\nOnion",
                Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Grill or broil chicken until charred.\n3. Sauté onion, garlic, and ginger.\n4. Add tomato sauce and spices, simmer 15 minutes.\n5. Add cream and cooked chicken.\n6. Simmer 10 minutes and serve with rice or naan.",
                Ratings = [5, 4, 5, 5, 4]
            },
            new Recipe
            {
                Id = 4, Title = "Vegetable Pad Thai", Category = "Asian",
                Ingredients = "Rice noodles\nTofu\nBean sprouts\nGreen onions\nPeanuts\nLime\nTamarind paste\nFish sauce\nSugar\nGarlic",
                Steps = "1. Soak rice noodles in warm water for 30 minutes.\n2. Press and cube tofu, then pan-fry until golden.\n3. Make sauce: mix tamarind paste, fish sauce, and sugar.\n4. Stir-fry garlic, then add noodles and sauce.\n5. Add tofu and bean sprouts.\n6. Serve with crushed peanuts, green onions, and lime.",
                Ratings = [4, 4, 3]
            },
            new Recipe
            {
                Id = 5, Title = "Beef Tacos", Category = "Mexican",
                Ingredients = "Ground beef\nTaco seasoning\nCorn tortillas\nLettuce\nTomato\nCheddar cheese\nSour cream\nSalsa",
                Steps = "1. Brown ground beef in a skillet.\n2. Add taco seasoning and water, simmer 5 minutes.\n3. Warm tortillas in a dry pan.\n4. Assemble tacos with beef, lettuce, tomato, and cheese.\n5. Top with sour cream and salsa.",
                Ratings = [4, 5, 4, 5]
            },
            new Recipe
            {
                Id = 6, Title = "Guacamole", Category = "Mexican",
                Ingredients = "Avocados\nLime juice\nCilantro\nRed onion\nJalapeño\nTomato\nSalt\nGarlic",
                Steps = "1. Halve and pit avocados, scoop into a bowl.\n2. Mash to desired consistency.\n3. Stir in diced onion, tomato, jalapeño, and cilantro.\n4. Add lime juice, garlic, and salt to taste.\n5. Serve immediately with tortilla chips.",
                Ratings = [5, 5, 5]
            },
            new Recipe
            {
                Id = 7, Title = "Miso Ramen", Category = "Asian",
                Ingredients = "Ramen noodles\nMiso paste\nChicken broth\nSoy sauce\nSoft-boiled egg\nGreen onions\nCorn\nNori\nChashu pork",
                Steps = "1. Bring chicken broth to a simmer.\n2. Dissolve miso paste into the broth.\n3. Cook ramen noodles according to package.\n4. Place noodles in a bowl, ladle broth over.\n5. Top with sliced chashu, soft-boiled egg, corn, nori, and green onions.",
                Ratings = [5, 4, 5, 5]
            },
            new Recipe
            {
                Id = 8, Title = "Chocolate Chip Cookies", Category = "Desserts",
                Ingredients = "Butter\nSugar\nBrown sugar\nEggs\nVanilla\nFlour\nBaking soda\nSalt\nChocolate chips",
                Steps = "1. Cream butter and sugars until fluffy.\n2. Beat in eggs and vanilla.\n3. Mix flour, baking soda, and salt, then combine with wet ingredients.\n4. Fold in chocolate chips.\n5. Drop spoonfuls onto baking sheet.\n6. Bake at 375°F (190°C) for 9-11 minutes.",
                Ratings = [5, 5, 4, 5, 5]
            },
            new Recipe
            {
                Id = 9, Title = "Tiramisu", Category = "Desserts",
                Ingredients = "Ladyfinger biscuits\nEspresso\nMascarpone cheese\nEggs\nSugar\nCocoa powder\nMarsala wine",
                Steps = "1. Brew espresso and let cool; mix with Marsala wine.\n2. Separate eggs; whisk yolks with sugar until pale.\n3. Fold mascarpone into yolk mixture.\n4. Whip egg whites to stiff peaks, fold into mascarpone mixture.\n5. Dip ladyfingers in espresso and layer in a dish.\n6. Spread cream over ladyfingers. Repeat layers.\n7. Refrigerate 4+ hours. Dust with cocoa before serving.",
                Ratings = [5, 5, 5, 4]
            },
            new Recipe
            {
                Id = 10, Title = "Dal Tadka", Category = "Indian",
                Ingredients = "Yellow lentils\nTurmeric\nTomatoes\nOnion\nGarlic\nCumin seeds\nMustard seeds\nDried red chilies\nGhee\nCilantro",
                Steps = "1. Wash lentils and cook with turmeric until soft.\n2. In a separate pan, heat ghee.\n3. Add cumin seeds, mustard seeds, and dried chilies — let them splutter.\n4. Add chopped onion and garlic, sauté until golden.\n5. Add chopped tomatoes and cook until soft.\n6. Pour the tempering over cooked lentils and stir.\n7. Garnish with cilantro and serve with rice or roti.",
                Ratings = [4, 5, 4]
            },
        ];
        _nextId = 11;
    }

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.Ratings.Add(stars);
        }
    }

    public void AddRecipe(string title, string category, string ingredients, string steps)
    {
        _recipes.Add(new Recipe
        {
            Id = _nextId++,
            Title = title,
            Category = category,
            Ingredients = ingredients,
            Steps = steps
        });
    }
}

